def is_prime(num: int) -> bool:
    # Base cases: 0 and 1 are not prime
    if num <= 1:
        return False
    # Check for small prime numbers (2 and 3)
    elif num <= 3:
        return True
    # Check if the number is divisible by 2 or 3
    elif num % 2 == 0 or num % 3 == 0:
        return False
    # Check for factors starting from 5 to the square root of the number
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

