def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a table to store the maximum volume that can be occupied with any subset of the first i items
    max_volume = [0] * (n + 1)

    # Base case: the maximum volume for 0 items is 0
    max_volume[0] = 0

    # Fill the table using dynamic programming
    for i in range(1, n + 1):
        for j in range(V - volumes[i - 1], -1, -1):
            if max_volume[j] + volumes[i - 1] <= V:
                max_volume[j + volumes[i - 1]] = max(max_volume[j + volumes[i - 1]], max_volume[j] + volumes[i - 1])

    # The minimum remaining space is the total capacity minus the maximum volume occupied
    min_remaining = V - max_volume[n]

    return min_remaining

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Both key and ciphertext should consist of alphabetic characters.")

    alphabet = 'abcdefghijklmnopqrstuvwxyz'

    plaintext = []
    key_index = 0

    for char in ciphertext:
        char_index = alphabet.index(char)
        plain_char_index = (char_index - key.index(key[key_index])) % 26
        plaintext.append(alphabet[plain_char_index])
        key_index = (key_index + 1) % len(key)

    return ''.join(plaintext)

